  describe "error_handling_invalid_syntax" do
    test "error_handling_invalid_syntax" do
      config_value = %TreeSitterLanguagePack.ProcessConfig{language: "javascript"}
      {:ok, result} = TreeSitterLanguagePack.process("function function function @@@ %%%", config_value)
    end
  end

  describe "error_handling_unknown_language" do
    test "error_handling_unknown_language" do
      config_value = %TreeSitterLanguagePack.ProcessConfig{language: "nonexistent_xyz"}
      assert {:error, _} = TreeSitterLanguagePack.process("", config_value)
    end
  end

  describe "error_process_empty_source" do
    test "error_process_empty_source" do
      config_value = %TreeSitterLanguagePack.ProcessConfig{language: "python"}
      {:ok, result} = TreeSitterLanguagePack.process("", config_value)
      assert result.metrics.total_lines == 0
    end
  end

  describe "parse_empty_language" do
    test "parse_empty_language" do
      config_value = %TreeSitterLanguagePack.ProcessConfig{language: ""}
      assert {:error, _} = TreeSitterLanguagePack.process("x = 1", config_value)
    end
  end

  describe "process_unknown_language" do
    test "process_unknown_language" do
      config_value = %TreeSitterLanguagePack.ProcessConfig{language: "nonexistent_xyz"}
      assert {:error, _} = TreeSitterLanguagePack.process("x = 1", config_value)
    end
  end
end
